#!/bin/bash
# SPDX-License-Identifier: GPL-3.0-or-later
# Copyright (C) 2026 MacroStat contributors
# ==============================================================================
# MacroStat uninstaller.
# Removes only the files installed by MacroStat:
#   - menu/desktop shortcuts marked X-MacroStat-Autogenerated=true
#   - the icon file, only if it is identical to the shipped one
#   - the udev rule, only if its content matches ours exactly
# User files, the profile (unless --purge-profile is given), logs and system
# packages are NEVER removed; repository sources are left untouched.
# ==============================================================================
set -euo pipefail

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd)"

# shellcheck source=packaging/install-common.sh
source "$DIR/packaging/install-common.sh"

DEFAULT_RULES="/etc/udev/rules.d/99-macrostat.rules"

is_ours() {
    grep -q '^X-MacroStat-Autogenerated=true$' "$1" 2>/dev/null
}

remove_file() {
    local path="$1"
    if rm -f "$path" 2>/dev/null; then
        return 0
    fi
    run_privileged rm -f "$path"
}

main() {
    local purge_profile=0
    while [ $# -gt 0 ]; do
        case "$1" in
            --purge-profile) purge_profile=1 ;;
            -h|--help)
                printf 'Usage: %s [--purge-profile]\n' "$0"
                printf '  --purge-profile  Also delete the user profile (default: kept)\n'
                return 0
                ;;
            *) printf '❌ Unknown option: %s\n' "$1" >&2; return 1 ;;
        esac
        shift
    done

    local target_user user_home
    target_user="${SUDO_USER:-${USER:-$(id -un)}}"
    user_home="${USER_HOME:-}"
    if [ -z "$user_home" ]; then
        user_home="$(getent passwd "$target_user" 2>/dev/null | awk -F: '{print $6}')"
    fi
    [ -n "$user_home" ] || user_home="$HOME"

    local apps_dir="${MACROSTAT_APPS_DIR:-$user_home/.local/share/applications}"
    local icon_dir="${MACROSTAT_ICON_DIR:-$user_home/.local/share/icons/hicolor/scalable/apps}"
    local rules_path="${MACROSTAT_RULES_PATH:-$DEFAULT_RULES}"
    local profile="${MACROSTAT_PROFILE_PATH:-$user_home/.config/macrostat/profile.json}"
    local removed=0 kept=0

    printf '🧹 Removing MacroStat (only files added by the installer)...\n'

    # Menu entry
    local menu_entry="$apps_dir/macrostat.desktop"
    if [ -e "$menu_entry" ]; then
        if is_ours "$menu_entry"; then
            remove_file "$menu_entry"
            removed=$((removed + 1))
        else
            printf '   ⚠️  %s looks like your own file; kept.\n' "$menu_entry"
            kept=$((kept + 1))
        fi
    fi

    # Desktop shortcut (including the localized XDG directory)
    local desktop_dir desktop_entry
    desktop_dir="$(HOME="$user_home" USER_HOME="$user_home" detect_desktop_dir)"
    desktop_entry="$desktop_dir/MacroStat.desktop"
    if [ -e "$desktop_entry" ]; then
        if is_ours "$desktop_entry"; then
            remove_file "$desktop_entry"
            removed=$((removed + 1))
        else
            printf '   ⚠️  %s looks like your own file; kept.\n' "$desktop_entry"
            kept=$((kept + 1))
        fi
    fi

    # Icon: remove only if it is identical to the installed one.
    local icon="$icon_dir/macrostat.svg"
    if [ -e "$icon" ]; then
        if cmp -s "$icon" "$DIR/assets/macrostat.svg"; then
            remove_file "$icon"
            removed=$((removed + 1))
        else
            printf '   ⚠️  %s was modified; kept.\n' "$icon"
            kept=$((kept + 1))
        fi
    fi

    # udev rule: remove only if it matches our content exactly.
    if [ -e "$rules_path" ]; then
        if cmp -s "$rules_path" <(udev_rule_content); then
            remove_file "$rules_path"
            removed=$((removed + 1))
            if [ "$rules_path" = "$DEFAULT_RULES" ] &&
                    command -v udevadm >/dev/null 2>&1; then
                run_privileged udevadm control --reload-rules || true
                run_privileged udevadm trigger || true
            fi
        else
            printf '   ⚠️  %s contains a different rule; kept.\n' "$rules_path"
            kept=$((kept + 1))
        fi
    fi

    # The profile is kept by default (user data).
    if [ "$purge_profile" -eq 1 ] && [ -e "$profile" ]; then
        remove_file "$profile"
        rmdir "$(dirname "$profile")" 2>/dev/null || true
        printf '   🗑️  Profile deleted: %s\n' "$profile"
    elif [ -e "$profile" ]; then
        printf '   ℹ️  Profile kept: %s (use --purge-profile to delete it)\n' "$profile"
    fi

    printf '✅ Uninstall complete. Removed: %d, kept: %d\n' \
        "$removed" "$kept"
    printf '   Note: Rust build outputs, logs and system packages were not removed.\n'
}

main "$@"
